// Filtra apenas mensagens de agentes humanos enviadas no Chatwoot
// Ignora mensagens do bot, eventos de criacao de conversa, etc.
const body = $json.body ?? $json;

const eventType = body.event;
const messageType = body.message_type; // 'outgoing' = agente enviou
const contentType = body.content_type;
const content = body.content;
const conversationId = body.conversation?.id;
const inboxId = body.inbox_id;

// So processa: novo outgoing message (agente respondeu)
if (eventType !== 'message_created') {
  return [{ json: { skip: true, reason: 'evento_ignorado_' + eventType } }];
}

if (messageType !== 'outgoing') {
  return [{ json: { skip: true, reason: 'nao_e_resposta_do_agente' } }];
}

if (!content || !content.trim()) {
  return [{ json: { skip: true, reason: 'conteudo_vazio' } }];
}

// Extrai numero do cliente a partir dos atributos da conversa
// O numero foi armazenado como atributo quando a conversa foi criada
const phone = body.conversation?.meta?.sender?.phone_number
  || body.meta?.sender?.phone_number
  || body.conversation?.additional_attributes?.from
  || null;

if (!phone) {
  return [{ json: { skip: true, reason: 'sem_numero_destinatario' } }];
}

// Normaliza numero (remove + e espacos)
const phoneCleaned = phone.replace(/[^0-9]/g, '');

return [{ json: {
  skip: false,
  to: phoneCleaned,
  content: content.trim(),
  conversationId,
  inboxId
} }];

